// INA219 with A1=A0=GND (0x40) and a 0.1 ohm shunt
const ADDR = 0x40, RSHUNT = 0.1;
// Pick a scale: up to 3.2 A, so Current_LSB = 3.2 / 2^15 ~ 100 uA.
const currentLsb = 0.0001;
const cal = Math.trunc(0.04096 / (currentLsb * RSHUNT));
i2c.writeReg16(ADDR, 0x05, cal);
log('Calibration =', cal, '(' + hex(cal) + ')');

const shunt = toInt16(i2c.readReg16(ADDR, 0x01)) * 10e-6;      // volts
const vbus = (i2c.readReg16(ADDR, 0x02) >> 3) * 0.004;         // volts
const amps = toInt16(i2c.readReg16(ADDR, 0x04)) * currentLsb;
const watts = i2c.readReg16(ADDR, 0x03) * 20 * currentLsb;
log('shunt', (shunt * 1000).toFixed(2), 'mV | bus', vbus.toFixed(3), 'V');
log('current', amps.toFixed(4), 'A | power', watts.toFixed(3), 'W');
